# Review package: a882d33219c8285f6c6dabb09711a593c48640b5..ba52b441ae6d1986357ae74758e4b42c6265e1cf

## Commits
ba52b44 Add greet function with tests

## Files changed
 greet.js      |  8 ++++++++
 greet.test.js | 31 +++++++++++++++++++++++++++++++
 2 files changed, 39 insertions(+)

## Diff
diff --git a/greet.js b/greet.js
new file mode 100644
index 0000000..5a9f66f
--- /dev/null
+++ b/greet.js
@@ -0,0 +1,8 @@
+function greet(name) {
+  if (!name) {
+    return 'Hello, there!';
+  }
+  return `Hello, ${name}!`;
+}
+
+module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
new file mode 100644
index 0000000..4231bc1
--- /dev/null
+++ b/greet.test.js
@@ -0,0 +1,31 @@
+const test = require('node:test');
+const assert = require('node:assert');
+const { greet } = require('./greet');
+
+test('greet returns formatted greeting for a name', () => {
+  const result = greet('Alice');
+  assert.strictEqual(result, 'Hello, Alice!');
+});
+
+test('greet returns formatted greeting for another name', () => {
+  const result = greet('Bob');
+  assert.strictEqual(result, 'Hello, Bob!');
+});
+
+test('greet handles empty string gracefully', () => {
+  const result = greet('');
+  assert.strictEqual(typeof result, 'string');
+  assert.ok(result.length > 0);
+});
+
+test('greet handles null gracefully', () => {
+  const result = greet(null);
+  assert.strictEqual(typeof result, 'string');
+  assert.ok(result.length > 0);
+});
+
+test('greet handles undefined gracefully', () => {
+  const result = greet(undefined);
+  assert.strictEqual(typeof result, 'string');
+  assert.ok(result.length > 0);
+});
